import {useState,useEffect} from "react"
import axios from "axios"

function App(){

const [name,setName] = useState("")
const [age,setAge] = useState("")
const [course,setCourse] = useState("")
const [students,setStudents] = useState([])


// get students

const getStudents = async ()=>{

const res = await axios.get("http://localhost:5000/students")

setStudents(res.data)

}


// add student

const addStudent = async ()=>{

await axios.post("http://localhost:5000/addStudent",{

name:name,
age:age,
course:course,
status:"enrolled"

})

getStudents()

}


// delete student

const deleteStudent = async(id)=>{

await axios.delete("http://localhost:5000/delete/"+id)

getStudents()

}


// update student

const updateStudent = async(id)=>{

await axios.put("http://localhost:5000/updateStatus/"+id)

getStudents()

}


useEffect(()=>{

getStudents()

},[])



return(

<div style={{padding:"40px"}}>

<h2>Student Database</h2>

<input placeholder="Name" onChange={(e)=>setName(e.target.value)}/>

<input placeholder="Age" onChange={(e)=>setAge(e.target.value)}/>

<input placeholder="Course" onChange={(e)=>setCourse(e.target.value)}/>

<button onClick={addStudent}>Add Student</button>

<hr/>

{students.map((s)=>{

return(

<div key={s._id}>

<h3>{s.name}</h3>

<p>Age : {s.age}</p>

<p>Course : {s.course}</p>

<p>Status : {s.status}</p>

<button onClick={()=>updateStudent(s._id)}>Complete</button>

<button onClick={()=>deleteStudent(s._id)}>Delete</button>

<hr/>

</div>

)

})}

</div>

)

}

export default App
